:root {
  --bg: #1b1f3b;
  --card: #2a2f5a;
  --accent: #7bdff2;
  --accent-strong: #b2f7ef;
  --text: #f7f7ff;
  --muted: #a9b0d6;
  --shadow: rgba(0, 0, 0, 0.35);
  --radius: 16px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: radial-gradient(circle at top, #2a2f5a 0%, var(--bg) 60%);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 480px;
  padding: 32px 24px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: 0 20px 40px var(--shadow);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

h1 {
  margin: 0;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.stage {
  width: 220px;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(123, 223, 242, 0.08);
  border: 2px dashed rgba(123, 223, 242, 0.35);
  transition: border-color 0.3s ease;
}

.circle {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--accent-strong));
  box-shadow: 0 0 24px rgba(123, 223, 242, 0.6);
  transition: width 0.1s linear, height 0.1s linear;
  will-change: width, height;
}

.phase-label {
  margin: 0;
  font-size: 1.4rem;
  font-weight: 600;
  min-height: 2rem;
  color: var(--accent-strong);
}

.counter {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1rem;
  color: var(--muted);
}

.counter-value {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text);
  min-width: 2ch;
  text-align: center;
}

.controls {
  display: flex;
  gap: 16px;
  width: 100%;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 140px;
  max-width: 200px;
  padding: 14px 20px;
  font-family: var(--font);
  font-size: 1.05rem;
  font-weight: 600;
  border-radius: 12px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.1s ease, background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.btn-primary {
  background: var(--accent);
  color: #10203a;
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
}

.btn-secondary {
  background: transparent;
  color: var(--accent-strong);
  border-color: var(--accent-strong);
}

.btn-secondary:hover:not(:disabled) {
  background: rgba(178, 247, 239, 0.12);
}

.btn:active:not(:disabled) {
  transform: translateY(2px);
}

.btn:focus-visible {
  outline: 3px solid var(--accent-strong);
  outline-offset: 3px;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

@media (max-width: 420px) {
  body {
    padding: 16px;
    font-size: 16px;
  }
  .card {
    padding: 24px 16px;
  }
  .stage {
    width: 180px;
    height: 180px;
  }
  .btn {
    flex-basis: 120px;
  }
}

(function () {
  'use strict';

  var INHALE_MS = 4000;
  var EXHALE_MS = 4000;
  var MIN_SIZE = 60;
  var MAX_SIZE = 180;

  var circle = document.getElementById('circle');
  var phaseLabel = document.getElementById('phase-label');
  var cycleCountEl = document.getElementById('cycle-count');
  var startBtn = document.getElementById('start-btn');
  var stopBtn = document.getElementById('stop-btn');

  var running = false;
  var phase = 'idle'; // 'idle' | 'inhale' | 'exhale'
  var cycles = 0;
  var phaseStart = 0;
  var rafId = null;

  function setSize(size) {
    circle.style.width = size + 'px';
    circle.style.height = size + 'px';
  }

  function updateLabel(text) {
    phaseLabel.textContent = text;
  }

  function updateCycle() {
    cycleCountEl.textContent = String(cycles);
  }

  function tick(now) {
    if (!running) return;

    var elapsed = now - phaseStart;
    var progress = Math.min(elapsed / (phase === 'inhale' ? INHALE_MS : EXHALE_MS), 1);

    if (phase === 'inhale') {
      setSize(MIN_SIZE + (MAX_SIZE - MIN_SIZE) * progress);
      if (progress >= 1) {
        phase = 'exhale';
        phaseStart = now;
        updateLabel('Exhale');
        setSize(MAX_SIZE);
      }
    } else if (phase === 'exhale') {
      setSize(MAX_SIZE - (MAX_SIZE - MIN_SIZE) * progress);
      if (progress >= 1) {
        cycles += 1;
        updateCycle();
        phase = 'inhale';
        phaseStart = now;
        updateLabel('Inhale');
        setSize(MIN_SIZE);
      }
    }

    rafId = requestAnimationFrame(tick);
  }

  function start() {
    if (running) return;
    running = true;
    phase = 'inhale';
    phaseStart = performance.now();
    setSize(MIN_SIZE);
    updateLabel('Inhale');
    startBtn.disabled = true;
    stopBtn.disabled = false;
    rafId = requestAnimationFrame(tick);
  }

  function stop() {
    if (!running) return;
    running = false;
    phase = 'idle';
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    setSize(MIN_SIZE);
    updateLabel('Ready');
    startBtn.disabled = false;
    stopBtn.disabled = true;
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);

  setSize(MIN_SIZE);
})();
